const $=s=>document.querySelector(s),canvas=$('#world'),ctx=canvas.getContext('2d'),data=await fetch('data.json').then(r=>r.json()),images={};
const paths=['forest_open','forest_open_road','forest_tree','forest_road','forest_gate'].map(n=>[n,`world/forest/image/tile/${n}.png`]).concat(['forest_small_tree','forest_road_flower'].map(n=>[n,`world/forest/image/object/${n}.png`]),['blank','mark','pin'].map(n=>[n,`world/common/image/object/${n}.png`]));
await Promise.all(paths.map(async([n,p])=>{const img=new Image();img.src='assets/'+p;await img.decode();images[n]=img;}));
for(const name of ['tiling','forest']){let row=document.createElement('div');row.className='logo-row';for(let i=1;i<=6;i++){let img=new Image();img.src=`assets/world/common/image/logo/${name}/${i}.png`;img.alt='';row.append(img);}$('#logo').append(row);}
const SAVE='tiling-forest-web-v1',SETTINGS='tiling-forest-settings-v1';let prefs={sound:false,volume:.25,grid:true,labels:true};try{Object.assign(prefs,JSON.parse(localStorage.getItem(SETTINGS)||'{}'));}catch{}
