let cam=stored?.camera||{x:3,y:21.7,scale:2.5},mode='tile',selected=forest.available()[0],markIndex=0,hover=null,currentArea='ecd7',started=false,dirty=true,paletteSignature='',toastTimer,rewardTimer,collapse=false,space=false;
let W=innerWidth,H=innerHeight,dpr=devicePixelRatio||1;const audio=new Audio('assets/world/forest/audio/background.mp3');audio.loop=true;audio.preload='none';audio.volume=prefs.volume*.45;const effects={};
function sound(name){if(!prefs.sound)return;let a=effects[name]||(effects[name]=new Audio(`assets/world/common/audio/effect/${name}.wav`));a.volume=prefs.volume;a.currentTime=0;a.play().catch(()=>{});}
function audioSync(){audio.volume=prefs.volume*.45;$('#soundBtn').style.opacity=prefs.sound?'1':'.5';$('#soundBtn').title=prefs.sound?'关闭声音':'开启声音';if(prefs.sound&&started)audio.play().catch(()=>{});else audio.pause();try{localStorage.setItem(SETTINGS,JSON.stringify(prefs));}catch{}}
function save(){try{localStorage.setItem(SAVE,JSON.stringify({game:forest.save(),camera:cam}));$('#saveStatus').textContent='✓ 已自动保存';}catch{$('#saveStatus').textContent='存储不可用 · 请导出存档';}}
