function size(){W=canvas.clientWidth;H=canvas.clientHeight;dpr=Math.min(devicePixelRatio||1,2);canvas.width=Math.round(W*dpr);canvas.height=Math.round(H*dpr);dirty=true;}
window.addEventListener('resize',()=>{size();refresh();});size();
function sprite(g,ref,x,y,s){if(!ref)return;const [name,pos]=ref.split(':'),im=images[name];if(!im)return;const [sx,sy]=pos.split(',').map(Number);g.drawImage(im,sx*32,sy*32,32,32,x,y,s,s);}
function tile(g,id,x,y,s,k){const def=forest.defs[id];if(!def)return;let sp=def.sprite||def.sprites?.[''];if(k&&def.sprites){const state=forest.formed.has(k)?'.formed':forest.flowers.get(k)?'.'+forest.flowers.get(k):'';sp=def.sprites[state]||sp;}if(typeof sp==='string')sprite(g,sp,x,y,s);else if(sp){sprite(g,sp.texture,x,y,s);if(sp.object)sprite(g,sp.object,x,y,s);if(sp.objects){sprite(g,sp.objects[0],x,y,s);sprite(g,sp.objects[1],x,y-s,s);}}}
