function screen(x,y){const s=32*cam.scale;return [W/2+(x-cam.x)*s,H/2+(y-cam.y)*s];}
function gridPoint(x,y){return [Math.floor(cam.x+(x-W/2)/(32*cam.scale)),Math.floor(cam.y+(y-H/2)/(32*cam.scale))];}
function setMode(m){mode=m;for(const [id,v]of [['handBtn','hand'],['tileBtn','tile'],['eraseBtn','erase'],['markBtn','mark']]){$('#'+id).classList.toggle('active',m===v);$('#'+id).setAttribute('aria-pressed',String(m===v));}paletteSignature='';refresh();dirty=true;}
// Fit the map into the space between the mobile controls, not behind them.
function playRect(){
 if(!isCompact())return {left:130,top:85,right:W-30,bottom:H-155};
 const top=Math.max($('header').getBoundingClientRect().bottom,$('.camera-controls').getBoundingClientRect().bottom)+12;
 const bottom=Math.min($('#palettePanel').getBoundingClientRect().top,$('#tools').getBoundingClientRect().top)-12;
 return {left:16,top,right:W-16,bottom:Math.max(top+80,bottom)};
}
function centerMap(x,y,scale){const r=playRect();cam={scale,x:x-((r.left+r.right)/2-W/2)/(32*scale),y:y-((r.top+r.bottom)/2-H/2)/(32*scale)};}
function focusArea(id){
 const keys=forest.blocks.get(id);if(!keys)return;
 const cs=keys.map(k=>forest.cells.get(k)),xs=cs.map(c=>c.x),ys=cs.map(c=>c.y),r=playRect();
 const minX=Math.min(...xs),maxX=Math.max(...xs),minY=Math.min(...ys),maxY=Math.max(...ys);
 const scale=clampScale(Math.min(3,(r.right-r.left)/((maxX-minX+3)*32),(r.bottom-r.top)/((maxY-minY+3)*32)));
 centerMap((minX+maxX+1)/2,(minY+maxY+1)/2,scale);currentArea=id;refresh();dirty=true;save();
}
function zoom(f){const r=playRect(),x=(r.left+r.right)/2,y=(r.top+r.bottom)/2,wx=cam.x+(x-W/2)/(32*cam.scale),wy=cam.y+(y-H/2)/(32*cam.scale);centerMap(wx,wy,clampScale(cam.scale*f));dirty=true;refresh();save();}
function overview(){const cs=[...forest.cells.values()],xs=cs.map(c=>c.x),ys=cs.map(c=>c.y),r=playRect();const scale=clampScale(Math.min((r.right-r.left)/((Math.max(...xs)-Math.min(...xs)+2)*32),(r.bottom-r.top)/((Math.max(...ys)-Math.min(...ys)+2)*32)));centerMap((Math.min(...xs)+Math.max(...xs)+1)/2,(Math.min(...ys)+Math.max(...ys)+1)/2,scale);dirty=true;refresh();save();}
function render(){requestAnimationFrame(render);if(!dirty)return;dirty=false;ctx.setTransform(dpr,0,0,dpr,0,0);ctx.imageSmoothingEnabled=false;ctx.fillStyle='#56896f';ctx.fillRect(0,0,W,H);
 const s=32*cam.scale,minX=Math.floor(cam.x-W/(2*s))-1,maxX=Math.ceil(cam.x+W/(2*s))+1,minY=Math.floor(cam.y-H/(2*s))-1,maxY=Math.ceil(cam.y+H/(2*s))+2;
 for(let y=minY;y<=maxY;y++)for(let x=minX;x<=maxX;x++){const [px,py]=screen(x,y);sprite(ctx,'forest_open:0,0',Math.round(px),Math.round(py),Math.ceil(s));}
 const visible=[...forest.cells.values()].filter(c=>c.x>=minX&&c.x<=maxX&&c.y>=minY&&c.y<=maxY).sort((a,b)=>a.y-b.y||a.x-b.x);
 for(const c of visible){const [px,py]=screen(c.x,c.y),x=Math.round(px),y=Math.round(py),n=Math.ceil(s),id=forest.tile(c.k);if(id)tile(ctx,id,x,y,n,c.k);else sprite(ctx,`blank:${(c.x+c.y)%2===0?0:1},0`,x,y,n);if(c.block&&!forest.unlocked.has(c.block)){ctx.fillStyle='#12251c8c';ctx.fillRect(x,y,n,n);}if(c.block&&prefs.grid&&cam.scale>.65){ctx.strokeStyle='#203b2c80';ctx.lineWidth=Math.max(.5,cam.scale*.45);ctx.strokeRect(x,y,s,s);}if(c.fixed&&c.block&&cam.scale>1)sprite(ctx,'pin:0,0',x,y,n);}
 // Boundaries follow original irregular area shapes, not their bounding rectangles.
 for(const c of visible){if(!c.block)continue;const [x,y]=screen(c.x,c.y);const done=forest.status.get(c.block)?.complete,unlocked=forest.unlocked.has(c.block);ctx.strokeStyle=done?'#b6d980':unlocked?(c.block===currentArea?'#f6d88e':'#93d187'):'#647b61';ctx.lineWidth=c.block===currentArea?2.4:1.5;ctx.beginPath();for(const [d,[dx,dy]]of Object.entries(DIRS)){if(forest.cells.get(forest.neighbor(c.k,d))?.block===c.block)continue;if(d==='u'){ctx.moveTo(x,y);ctx.lineTo(x+s,y);}if(d==='d'){ctx.moveTo(x,y+s);ctx.lineTo(x+s,y+s);}if(d==='l'){ctx.moveTo(x,y);ctx.lineTo(x,y+s);}if(d==='r'){ctx.moveTo(x+s,y);ctx.lineTo(x+s,y+s);}}ctx.stroke();}
 if(prefs.labels&&cam.scale>.48)for(const [id,keys]of forest.blocks){const cells=keys.map(k=>forest.cells.get(k)),c=cells.reduce((a,b)=>a.y<b.y||a.y===b.y&&a.x<b.x?a:b),[x,y]=screen(c.x,c.y);if(y<-50||y>H||x<-100||x>W)continue;let txt=data.text.block_name[id]+(forest.status.get(id).complete?' ✓':!forest.unlocked.has(id)?' ···':'');ctx.font=`${Math.max(10,Math.min(14,cam.scale*9))}px Forest,sans-serif`;let tw=ctx.measureText(txt).width;ctx.fillStyle='#203126db';ctx.fillRect(x+2,y+3,tw+12,20);ctx.fillStyle=forest.status.get(id).complete?'#d2e4a0':'#f0e6bf';ctx.fillText(txt,x+8,y+17);}
 for(const c of visible){if(forest.marks[c.k]!==undefined){const[x,y]=screen(c.x,c.y);sprite(ctx,`mark:${forest.marks[c.k]},0`,x,y,s);}if(!c.block&&forest.def(c.k)?.path&&!forest.explored.has(c.k)&&cam.scale>1){const[x,y]=screen(c.x,c.y);ctx.fillStyle='#25372fcc';ctx.beginPath();ctx.arc(x+s/2,y+s/2,s*.13,0,Math.PI*2);ctx.fill();ctx.fillStyle='#ece6ba';ctx.font=`bold ${Math.max(10,s*.18)}px sans-serif`;ctx.textAlign='center';ctx.fillText('?',x+s/2,y+s*.56);ctx.textAlign='left';}}
 if(started&&hover&&!gestures.active&&mode!=='hand'){const c=forest.cells.get(hover),[gx,gy]=hover.split(',').map(Number),[x,y]=screen(gx,gy);if(c){const ok=mode==='mark'||(mode==='erase'?!!forest.placed[hover]:forest.canPlace(hover,selected));ctx.globalAlpha=.65;if(mode==='tile'&&!c.fixed)tile(ctx,selected,x,y,s);else if(mode==='mark')sprite(ctx,`mark:${markIndex},0`,x,y,s);ctx.globalAlpha=1;ctx.fillStyle=ok?'#dbe7a216':'#ed69512b';ctx.fillRect(x,y,s,s);ctx.strokeStyle=ok?'#fff4bd':'#ed8b7c';ctx.lineWidth=2;ctx.strokeRect(x+1,y+1,s-2,s-2);}}
}
requestAnimationFrame(render);
function refresh(){const count=[...forest.status.values()].filter(s=>s.complete).length;$('#progress').textContent=`${count} / 35`;$('#zoomLabel').textContent=Math.round(cam.scale*100)+'%';$('#undoBtn').disabled=!forest.undoStack.length;$('#redoBtn').disabled=!forest.redoStack.length;
 let st=forest.status.get(currentArea);$('#areaPanel').hidden=!st;if(st){$('#areaName').textContent=data.text.block_name[currentArea];$('#areaState').textContent=st.complete?'✓ 已完成':forest.unlocked.has(currentArea)?'未完成':'尚未到达';const rows=[[st.filled,`填满区域 ${st.filledCount} / ${st.total}`],[st.connected,'区域内道路连成一体'],[st.gates,'树桩成对发芽']];$('#areaChecks').innerHTML=rows.map(([ok,t])=>`<div class="${ok?'ok':''}">${ok?'✓':'○'}　${t}</div>`).join('');$('#resetArea').disabled=!forest.blocks.get(currentArea).some(k=>forest.placed[k]);$('#loadArea').disabled=!forest.snapshots[currentArea];}
 const avail=forest.available();if(!avail.includes(selected))selected=avail[0];const sig=mode+':'+avail.join(',')+':'+selected+':'+markIndex;if(sig!==paletteSignature){paletteSignature=sig;const scroll=$('#palette').scrollLeft;$('#palette').replaceChildren();$('#paletteCaption').textContent=mode==='mark'?'备忘标记':'拥有的图块';$('#tileCount').textContent=mode==='mark'?'8 种':`${avail.length} / 36`;const list=mode==='mark'?Array.from({length:8},(_,i)=>i):avail;list.forEach((id,i)=>{const b=document.createElement('button');b.className='tile'+((mode==='mark'?id===markIndex:id===selected)?' active':'');b.title=mode==='mark'?['完成','横向','纵向','排除','待定','加减','减号','加号'][id]:tileLabel(id);b.setAttribute('aria-label',b.title);b.setAttribute('aria-pressed',String(mode==='mark'?id===markIndex:id===selected));b.append(thumb(id));if(i<10){let n=document.createElement('small');n.textContent=(i+1)%10;b.append(n);}b.onclick=()=>{if(mode==='mark')markIndex=id;else{selected=id;setMode('tile');}sound('hover');refresh();dirty=true;};$('#palette').append(b);});$('#palette').scrollLeft=scroll;}
 $('#instruction').textContent=isCompact()?(mode==='erase'?'点击移除图块 · 单指拖动 · 双指缩放':mode==='mark'?'点击放置标记 · 再次点击移除':mode==='hand'?'单指拖动 · 双指缩放 · 选择图块开始拼图':'点击放置 · 单指拖动 · 双指缩放') : mode==='erase'?'点击移除图块 · 拖动移动地图':mode==='hand'?'拖动 / WASD 移动地图 · Q / E 缩放 · 点击「图块」继续拼图':mode==='mark'?'点击 放置标记 · 再次点击 移除标记 · 标记不影响谜题判定':'左键 放置 · 右键 移除 · 滚轮 切换图块 · 拖动 / WASD 移动';
}
function tileLabel(id){const map={'forest_road.2s.lr':'道路 · 横向','forest_road.2s.ud':'道路 · 纵向','forest_road.2t.ul':'弯道 · 左上','forest_road.2t.ur':'弯道 · 右上','forest_road.2t.dl':'弯道 · 左下','forest_road.2t.dr':'弯道 · 右下'};return map[id]||(id.startsWith('forest_tree')?'树冠 · '+id.split('.').pop():id.startsWith('forest_gate')?'树桩 · '+({u:'向上',d:'向下',l:'向左',r:'向右'}[id.split('.').pop()]):id.startsWith('forest_open_road')?'空地入口 · '+id.split('.').pop():'空地 · '+id.split('.').pop());}
function changed(){const completed=forest.justCompleted.slice();save();refresh();dirty=true;if(completed.length){sound('complete_block');let reward=forest.available().at(-1);$('#reward').replaceChildren();let strong=document.createElement('strong');strong.textContent=`${completed.map(id=>data.text.block_name[id]).join('、')} 完成！`;let text=document.createElement('div');text.textContent='获得新图块！';$('#reward').append(strong,thumb(reward,96),text);$('#reward').hidden=false;clearTimeout(rewardTimer);rewardTimer=setTimeout(()=>$('#reward').hidden=true,2500);if(forest.completed)setTimeout(()=>showMessage('森林完成！','所有区域、树桩和道路都已满足条件。恭喜你完全通关 Tiling Forest！'),2600);else if(completed.includes('3439'))setTimeout(()=>showMessage('Tiling Forest 通关！','你已完成 N-6，达成 demo 的通关条件。继续完成所有区域、让所有树桩发芽并让每条道路开花，挑战森林的完全完成。'),2600);}}
function act(k,button){const c=forest.cells.get(k);if(!c)return;if(c.block){currentArea=c.block;refresh();}if(mode==='hand')return;if(mode==='mark'){forest.mark(k,markIndex);sound('write');changed();return;}if(button===2||mode==='erase'){if(forest.erase(k)){sound('pop_1');changed();}return;}if(c.fixed){if(forest.available().includes(c.fixed)){selected=c.fixed;refresh();}return;}if(!forest.unlocked.has(c.block)){toast('这片区域尚未到达。请先将道路与已到达的道路连接。');return;}if(forest.place(k,selected)){sound('push');changed();}else if(forest.tile(k)!==selected){sound('koke');toast('图案不匹配：相邻边的道路与地形必须对齐。');}}
canvas.addEventListener('contextmenu',e=>e.preventDefault());
const gestures=new MapGestures({
 getCamera:()=>cam,getViewport:()=>({width:W,height:H}),
 setCamera:c=>{cam=c;hover=null;dirty=true;$('#zoomLabel').textContent=Math.round(cam.scale*100)+'%';},
 onTap:(x,y,button)=>{if(!space)act(gridPoint(x,y).join(','),button);},
 onEnd:()=>{hover=null;dirty=true;if(started)save();}
});
canvas.addEventListener('pointerdown',e=>{if(!started)return;canvas.setPointerCapture(e.pointerId);gestures.down(e);});
canvas.addEventListener('pointermove',e=>{hover=e.pointerType==='touch'?null:gridPoint(e.clientX,e.clientY).join(',');gestures.move(e);dirty=true;});
canvas.addEventListener('pointerup',e=>gestures.up(e));
canvas.addEventListener('pointercancel',e=>gestures.up(e,true));
canvas.addEventListener('lostpointercapture',e=>gestures.up(e,true));
canvas.addEventListener('pointerleave',()=>{hover=null;dirty=true;});
canvas.addEventListener('wheel',e=>{if(!started)return;e.preventDefault();if(e.ctrlKey||e.metaKey||mode==='hand'){zoom(e.deltaY>0?1/1.12:1.12);}else{const a=mode==='mark'?Array.from({length:8},(_,i)=>i):forest.available(),v=mode==='mark'?markIndex:selected,n=a[(a.indexOf(v)+(e.deltaY>0?1:-1)+a.length)%a.length];if(mode==='mark')markIndex=n;else selected=n;refresh();dirty=true;}},{passive:false});
function start(){started=true;$('#titleScreen').hidden=true;$('#gameUI').hidden=false;audioSync();refresh();dirty=true;if(!forest.earned.size)toast('欢迎来到 Tiling Forest！用手中的图块填满 W-1 区域。');}
$('#continue').hidden=!stored;$('#start').textContent=stored?'重新开始':'开始游戏';$('#continue').onclick=start;$('#start').onclick=()=>{if(stored)newGamePrompt();else{start();focusArea('ecd7');}};
function newGamePrompt(){openModal('开始新的森林',`<p>重新开始会替换此浏览器中的当前进度。可以先在菜单导出存档。</p><div class="menu-grid"><button id="confirmNew">重新开始</button><button id="cancelNew">取消</button></div>`);$('#confirmNew').onclick=()=>{forest=new Forest(data);stored=null;selected=forest.available()[0];paletteSignature='';closeModal();start();focusArea('ecd7');save();};$('#cancelNew').onclick=closeModal;}
function openModal(title,body){$('#modalTitle').textContent=title;$('#modalBody').innerHTML=body;if(!$('#modal').open)$('#modal').showModal();}
function closeModal(){$('#modal').close();dirty=true;}
function showMessage(title,text){openModal(title,`<p>${text}</p><button id="messageOK">继续探索</button>`);$('#messageOK').onclick=closeModal;}
$('#closeModal').onclick=closeModal;$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){const r=$('#modal').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeModal();}});
$('#handBtn').onclick=()=>setMode('hand');$('#tileBtn').onclick=()=>setMode('tile');$('#markBtn').onclick=()=>setMode('mark');$('#eraseBtn').onclick=()=>setMode('erase');$('#undoBtn').onclick=()=>{if(forest.undo()){sound('pop_1');changed();}};$('#redoBtn').onclick=()=>{if(forest.redo()){sound('push');changed();}};$('#home').onclick=()=>focusArea('ecd7');$('#overview').onclick=overview;$('#zoomIn').onclick=()=>zoom(1.25);$('#zoomOut').onclick=()=>zoom(.8);$('#resetArea').onclick=()=>{forest.resetBlock(currentArea);changed();};$('#loadArea').onclick=()=>{if(forest.loadBlock(currentArea)){sound('push');changed();}else toast('当前周边图案与保存的布局不匹配。');};$('#collapsePalette').onclick=()=>{collapse=!collapse;$('#palette').hidden=collapse;$('#collapsePalette').textContent=collapse?'⌃':'⌄';$('#collapsePalette').setAttribute('aria-expanded',String(!collapse));};$('#soundBtn').onclick=()=>{prefs.sound=!prefs.sound;audioSync();};$('#fullBtn').onclick=()=>{if(document.fullscreenElement)document.exitFullscreen?.();else document.documentElement.requestFullscreen?.().catch(()=>toast('此浏览器不支持全屏，请使用窗口最大化。'));};
function menu(){openModal('森林 · 菜单',`<div class="menu-grid"><button id="resumeGame">继续游戏</button><button id="returnTitle">返回标题</button><button id="exportSave">导出存档</button><button id="importSave">导入存档</button><button id="newGame">重新开始</button><button id="showAbout">关于移植</button></div><div class="settings-row"><label for="languageSetting">语言</label><select id="languageSetting"><option value="system">跟随系统</option><option value="en">English</option><option value="zh">简体中文</option><option value="ja">日本語</option></select></div><div class="settings-row">背景音乐与音效<input id="soundSetting" type="checkbox" ${prefs.sound?'checked':''}></div><div class="settings-row">音量<input id="volumeSetting" type="range" min="0" max="1" step="0.05" value="${prefs.volume}"></div><div class="settings-row">显示图块网格<input id="gridSetting" type="checkbox" ${prefs.grid?'checked':''}></div><div class="settings-row">显示区域名称<input id="labelsSetting" type="checkbox" ${prefs.labels?'checked':''}></div><p class="muted">进度自动保存在当前浏览器。可以导入网页版存档或原版 progress.json。</p>`);
 $('#languageSetting').value=localization.preference;$('#languageSetting').onchange=e=>localization.set(e.target.value);$('#resumeGame').onclick=closeModal;$('#returnTitle').onclick=()=>{closeModal();save();started=false;$('#gameUI').hidden=true;$('#titleScreen').hidden=false;$('#continue').hidden=false;$('#start').textContent='重新开始';stored={game:forest.save()};audio.pause();};$('#exportSave').onclick=()=>{const url=URL.createObjectURL(new Blob([JSON.stringify(forest.save(),null,2)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download='tiling-forest-save.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};$('#importSave').onclick=()=>$('#importFile').click();$('#newGame').onclick=newGamePrompt;$('#showAbout').onclick=()=>openModal('关于移植',`<p>使用本地 Tiling Forest demo 提取的原版地图、图块规则定义、像素贴图、中文规则和音乐，在浏览器中重新实现游戏逻辑。</p><p>包含 35 个区域、36 档图块解锁、道路探索、树桩配对与花朵判定。原始素材及游戏设计版权归 muratsubo Games 及各自权利人所有。本项目为非官方移植。请支持<a href="https://store.steampowered.com/app/4213590/" target="_blank" rel="noopener">原版游戏</a>。</p><p class="muted">引擎由 OpenSiv3D / Direct3D 改写为 Canvas 2D。原版 Steam 成就和动态指南推理未接入；本版指南提供规则说明、区域定位和合法落子提示。</p>`);
 for(const [id,key]of [['soundSetting','sound'],['gridSetting','grid'],['labelsSetting','labels']])$('#'+id).onchange=e=>{prefs[key]=e.target.checked;audioSync();dirty=true;};$('#volumeSetting').oninput=e=>{prefs.volume=Number(e.target.value);audioSync();};}
$('#menuBtn').onclick=menu;
$('#importFile').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{const s=JSON.parse((await file.text()).replace(/^\uFEFF/,''));const next=new Forest(data,s.game||s);forest=next;selected=forest.available()[0];paletteSignature='';save();closeModal();start();overview();toast('存档已导入');}catch{toast('无法读取存档：请选择网页版存档或原版 progress.json。');}e.target.value='';};
function rules(){openModal('规则列表',`<div class="rule-grid"><div class="rule-card"><h3>图块的图案</h3><p>图块相邻边的<strong>道路和地形必须对齐</strong>。不能放置图案不匹配的图块。每种方向是独立图块，需要分别解锁。</p></div><div class="rule-card"><h3>完成一个区域</h3><p>填满所有空格，将<strong>区域内的道路连成一体</strong>，并让区域内的树桩全部发芽。完成后获得一种新图块。</p></div><div class="rule-card"><h3>道路与探索</h3><p>将道路连接到<strong>已到达的道路</strong>，即可到达新道路并解锁相连的区域。仅连接两条未探索道路，不能解锁区域。</p></div><div class="rule-card"><h3>空地</h3><p>进入同一空地的道路视为相互连接。空地本身不要求全部连接到道路。</p></div><div class="rule-card"><h3>树桩发芽</h3><p>两个树桩<strong>相向、间隔恰好一格</strong>，中间夹有道路时发芽。可以与区域外的树桩配对。</p></div><div class="rule-card"><h3>森林完全完成</h3><p>完成所有区域，让所有树桩发芽，让所有道路开花。道路必须被<strong>恰好一对</strong>发芽的树桩夹住；花朵遇到空地停止，两对以上会枯萎。</p></div></div><h3>通关目标</h3><p>找到并完成 <strong>N-6</strong> 即可通关 demo；再满足森林的全部条件，达成完全完成。</p><h3>触屏操作</h3><p>轻点格子放置图块；单指拖动移动地图，双指捏合缩放。选择「擦除」后轻点已放置的图块即可移除。底部图块栏可横向滑动，点击区域名称可展开详情。</p><h3>键鼠操作</h3><p>左键放置 · 右键移除 · 拖动 / WASD 移动 · Q / E 缩放<br>滚轮 / R / T 切换图块 · 1–0 快选 · Z 撤销 · X 重做<br>C 重置当前区域 · Tab 收起图块栏 · Esc 切换移动模式<br>通过菜单导出 / 导入存档；所有进度自动保存在浏览器。</p>`);}
$('#rulesBtn').onclick=rules;$('#titleRules').onclick=rules;
function guide(){const avail=forest.available(),unfinished=[...forest.unlocked].filter(id=>!forest.status.get(id).complete);openModal('森林指南',`<p>已完成 <strong>${[...forest.status.values()].filter(s=>s.complete).length} / 35</strong> 个区域，已获得 <strong>${avail.length} / 36</strong> 种图块。</p><div class="guide-tip"><p>${forest.cleared?'已通关！现在尝试让所有区域完成、所有树桩发芽、所有道路开花。':'目标：找到并完成北方区域 N-6。无法完成当前区域时，先寻找其他可以到达的道路。'}</p></div><h3>已到达的区域</h3><div class="area-list" id="areaList"></div><h3>当前区域 · ${data.text.block_name[currentArea]}</h3><p>提示检查当前已拥有的图块和相邻图案。一个合法落子并不保证最终可解；图块不够时，可以换一个区域探索。</p><button id="hintBtn">寻找一个合法落子</button><p class="muted">提示不会自动填图，也不会使用尚未解锁的图块。</p>`);
 for(const id of [...forest.unlocked].sort((a,b)=>data.text.block_name[a].localeCompare(data.text.block_name[b]))){const b=document.createElement('button');b.innerHTML=`${data.text.block_name[id]}<small>${forest.status.get(id).complete?'✓ 已完成':'未完成'}</small>`;b.onclick=()=>{focusArea(id);closeModal();};$('#areaList').append(b);}$('#hintBtn').onclick=()=>{if(!forest.unlocked.has(currentArea)){toast('先沿道路到达这个区域。');return;}let choices=forest.blocks.get(currentArea).filter(k=>!forest.tile(k)).map(k=>[k,avail.filter(t=>forest.canPlace(k,t))]).filter(([,ts])=>ts.length).sort((a,b)=>a[1].length-b[1].length);if(!choices.length){toast('当前没有可填的合法空格。尝试撤销布局或探索其他区域。');return;}let[k,ts]=choices[0];selected=ts[0];setMode('tile');focusArea(currentArea);hover=k;closeModal();toast(`已选中一个可放置图块。高亮格有 ${ts.length} 种合法选择。`);dirty=true;};}
$('#guideBtn').onclick=guide;
window.addEventListener('keydown',e=>{if($('#modal').open)return;if(!started)return;if(e.metaKey||e.ctrlKey)return;const k=e.key.toLowerCase();if([' ','tab','arrowup','arrowdown','arrowleft','arrowright'].includes(k))e.preventDefault();if(k===' '){space=true;return;}if(k==='escape'){setMode(mode==='hand'?'tile':'hand');return;}if(k==='g')return guide();if(k==='h')return rules();if(k==='z'){if(forest.undo())changed();return;}if(k==='x'){if(forest.redo())changed();return;}if(k==='c'){forest.resetBlock(currentArea);changed();return;}if(k==='tab')return $('#collapsePalette').click();if(k==='q')return zoom(.8);if(k==='e')return zoom(1.25);if(k==='home')return focusArea('ecd7');const moves={w:[0,-1],s:[0,1],a:[-1,0],d:[1,0],arrowup:[0,-1],arrowdown:[0,1],arrowleft:[-1,0],arrowright:[1,0]};if(moves[k]){cam.x+=moves[k][0]*.8;cam.y+=moves[k][1]*.8;dirty=true;return;}const a=mode==='mark'?Array.from({length:8},(_,i)=>i):forest.available();let n;if(/^\d$/.test(k))n=a[(Number(k)+9)%10];if(k==='r'||k==='t')n=a[(a.indexOf(mode==='mark'?markIndex:selected)+(k==='r'?-1:1)+a.length)%a.length];if(n!==undefined){if(mode==='mark')markIndex=n;else selected=n;refresh();dirty=true;}});
window.addEventListener('keyup',e=>{if(e.key===' ')space=false;});window.addEventListener('blur',()=>{space=false;gestures.cancel();});window.addEventListener('beforeunload',()=>{if(started)save();});document.addEventListener('visibilitychange',()=>{if(document.hidden){audio.pause();if(started)save();}else audioSync();});
refresh();audioSync();if(!stored){cam={x:15.5,y:11,scale:1.15};dirty=true;}

function areaDisclosure(){const expanded=!isCompact()||$('#areaPanel').classList.contains('expanded');$('#areaToggle').setAttribute('aria-expanded',String(expanded));$('#areaDetails').hidden=!expanded;$('#areaToggle').title=expanded?'收起区域详情':'展开区域详情';}
$('#areaToggle').onclick=()=>{if(!isCompact())return;$('#areaPanel').classList.toggle('expanded');areaDisclosure();};
compactMedia.addEventListener('change',()=>{areaDisclosure();refresh();});areaDisclosure();
$('#collapsePalette').setAttribute('aria-expanded','true');
document.fonts.ready.then(()=>{dirty=true;});

document.addEventListener('forest-languagechange',()=>{dirty=true;});
